sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var result = {};

    var gr = new GlideRecord('cmn_location'); // Replace with your actual table name

    // Filter locations where location, city, or country is empty
    gr.addQuery('location', ''); // Locations without a location
    gr.addQuery('city', '');     // Locations without a city
    gr.addQuery('country', '');  // Locations without a country
    gr.query();

    while (gr.next()) {
        var location = gr.getValue('location') || 'No Location';  // If location is empty, show 'No Location'
        var city = gr.getValue('city') || 'No City';              // If city is empty, show 'No City'
        var country = gr.getValue('country') || 'No Country';     // If country is empty, show 'No Country'

        // Combine location, city, and country to create a unique key for grouping
        var key = location + ' | ' + city + ' | ' + country;

        // Initialize the result entry if it does not already exist
        if (!result[key]) {
            result[key] = {
                location: location,
                city: city,
                country: country,
                count: 0
            };
        }

        // Increment the count for each unique group
        result[key].count++;
    }

    // Return the result as a JSON response
    response.setBody(Object.values(result)); // Convert the result object to an array for JSON response
})(request, response);
